-- =====================================================================
-- TÉCNICA · FASE 1 · DESCARGAS DE DISTRIBUCIÓN · 05 — HUELLAS DE SOLO LECTURA (una sola consulta; apta para el editor SQL web). No escribe nada.
-- ANTES: «funciones de redes» dice «AVISO POR CONTRATO (lista para las descargas)», las 22 nuevas «NO EXISTE» y las tablas «NO EXISTEN».
-- DESPUÉS: «DESCARGAS DE DISTRIBUCIÓN (aplicado)», las 22 «NUEVA» y las tablas «EXISTEN». Cualquier «DISTINTA» o «FALTA»: no aplique nada y avise.
-- =====================================================================
with nue(firma, nueva) as (values ('geoportal_redes_reporte_cerrar(text,bigint,integer,text,text)', '875ac07e496368d8947c5c803d658dc7'), ('geoportal_redes_reporte_iniciar(text,text,jsonb,text,boolean,text)', 'a9e666604f66f0676d3b26acba1091d7'), ('geoportal_redes_reporte_pagina(text,bigint,text,integer)', '5e55735ae8f7ad024627f1393aedefdd'), ('redes.f_rep_activos(jsonb,boolean,timestamp with time zone,text,integer,boolean)', '4e4f663f97dfebb12cdf2fbb04cfb962'), ('redes.f_rep_bot(jsonb,boolean,timestamp with time zone,text,integer,boolean)', '36044a733fd95d3a1e817c17666f7b05'), ('redes.f_rep_catalogo()', '467a1941f5fc3583e9d3b6c149507ea7'), ('redes.f_rep_col(text,text,text,text,integer)', 'cf16ae8bdb29a755236e8098b3e4f8a6'), ('redes.f_rep_columnas(text)', '4d0a437406c700fae3cf76d43d103691'), ('redes.f_rep_contar(text,jsonb,boolean,timestamp with time zone)', 'c0926aff859accf709ee59e56fb4d5f1'), ('redes.f_rep_eventos(jsonb,boolean,timestamp with time zone,text,integer,boolean)', 'ae2482e45f78d7593d5160d450be41c6'), ('redes.f_rep_filas(text,jsonb,boolean,timestamp with time zone,text,integer,boolean)', 'e85f272201e12b9108b85cac8d748e27'), ('redes.f_rep_filtros(text,jsonb)', 'c019c0aeaea7eb74b8e57dad8786ea7c'), ('redes.f_rep_l116(jsonb,boolean,timestamp with time zone,text,integer,boolean)', '95de0f3b2c95cbc8dd2695f65b5a2c0f'), ('redes.f_rep_leame(text,jsonb,boolean,text,timestamp with time zone)', 'e486098b914fdc275b4121b183119145'), ('redes.f_rep_levantamientos(jsonb,boolean,timestamp with time zone,text,integer,boolean)', '8ea7a74224a274215f374e658098b87f'), ('redes.f_rep_max_filas()', '64e8b7852af79a4b9983fec4edbc7aee'), ('redes.f_rep_punto(geometry)', '5701c68467a8dd5e738b91b89a8ef84d'), ('redes.f_rep_rotulo(text)', 'c837dc6b2d58acff6f3e96425a93347d'), ('redes.f_rep_sector_geom(integer)', '26684fc169e66c7a0819a868d958a8fd'), ('redes.f_rep_sensibles(jsonb,boolean,timestamp with time zone,text,integer,boolean)', 'cf2ab4f51d82ad171c80f85834a748df'), ('redes.f_rep_ts(timestamp with time zone)', '95b328ce9d7272918dd1614790216b4d'), ('redes.f_rep_valvulas(jsonb,timestamp with time zone,text,integer,boolean)', '56fc887ba3435bf4059df813c5a61ac0')),
pub(firma, publicada) as (values ('redes.f_supervisor(text,text)', 'da1844d42f25ce4ba6abeebe207869b3'), ('redes.f_perfil_lectura(text)', 'b16cdc53435687d24704b0af7770b0ff'), ('redes.f_sector_de(geometry)', '455378c9b8cf43343ff821a2896eae37'), ('redes.f_evento_reportes(bigint)', 'e9d6c5b2d72868e188e2bc5eeda47ddd'), ('public.geoportal_redes_descarga(text,text,date,date,boolean,text)', '6a45b63d76ee2e96d68439a14f238c1f'), ('public.geoportal_redes_reporte_convertir(text,uuid,jsonb)', 'c51e28695635e028403f0c85c7ded5f9'), ('public.geoportal_redes_reporte_descartar(text,uuid,text)', 'f070fb817ea878564a0274154ce5c042')),
conj as (
  select md5(string_agg(md5(pg_get_functiondef(p.oid)), '' order by p.pronamespace::regnamespace::text, p.proname)) as m from pg_proc p
   where p.pronamespace = 'redes'::regnamespace or (p.pronamespace = 'public'::regnamespace and p.proname like 'geoportal\_redes\_%'))
select '0 funciones de redes (conjunto)' as objeto, (select m from conj) as md5,
       case (select m from conj) when 'b474fbbe3e0f7a3a7e6dbc04c53e02e7' then 'AVISO POR CONTRATO (lista para las descargas)' when 'ef5fc9df2a7ba17df5797bc2971d2f04' then 'DESCARGAS DE DISTRIBUCIÓN (aplicado)' else 'DISTINTA' end as estado
union all select '1 las ' || count(*) || ' funciones nuevas', null,
       case when count(*) filter (where to_regprocedure(n.firma) is null) = count(*) then 'NO EXISTE (sin aplicar)'
            when count(*) filter (where md5(pg_get_functiondef(to_regprocedure(n.firma))) = n.nueva) = count(*) then 'NUEVA (aplicada)'
            else 'DISTINTA: ' || coalesce(string_agg(n.firma, ', ') filter (where to_regprocedure(n.firma) is null or md5(pg_get_functiondef(to_regprocedure(n.firma))) <> n.nueva), '') end
  from nue n
union all select '2 ' || p.firma || ' (no se toca)', md5(pg_get_functiondef(to_regprocedure(p.firma))),
       case when to_regprocedure(p.firma) is null then 'FALTA' when md5(pg_get_functiondef(to_regprocedure(p.firma))) = p.publicada then 'LA PUBLICADA' else 'DISTINTA' end from pub p
union all select '3 tablas nuevas (reporte_descargas, reporte_descarga_cierres)', null,
       case when to_regclass('redes.reporte_descargas') is null and to_regclass('redes.reporte_descarga_cierres') is null then 'NO EXISTEN (sin aplicar)'
            when to_regclass('redes.reporte_descargas') is not null and to_regclass('redes.reporte_descarga_cierres') is not null then 'EXISTEN (aplicado)' else 'A MEDIAS' end
union all select '4 INFO datos: LEV · cierres de válvula · eventos · 116 · bot · sensibles · activos · sectores', null,
       (select count(*) from redes.levantar_puntos) || ' · ' || (select count(*) from redes.valvula_maniobras where tipo = 'cerrar') || ' · ' || (select count(*) from redes.eventos_suspension)
       || ' · ' || (select count(*) from redes.l116_vigente) || ' · ' || (select count(*) from redes.reportes_externos) || ' · ' || (select count(*) from redes.usuarios_sensibles)
       || ' · ' || (select count(*) from redes.activo_vigente_mat) || ' · ' || (select count(*) from redes.activo_vigente_mat where prefijo = 'SEC' and not retirado and not oculto)
order by 1;
